import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

@RestController
class RefundController {

    private final RefundPayment refundPayment;

    RefundController(RefundPayment refundPayment) {
        this.refundPayment = refundPayment;
    }

    @PostMapping("/payments/{reference}/refunds")
    ResponseEntity<RefundResponse> refund(@PathVariable String reference, @RequestBody RefundRequest request) {
        Money amount;
        try {
            amount = new Money(request.amount(), request.currency());
        } catch (IllegalArgumentException | NullPointerException e) {
            return ResponseEntity.badRequest().build();
        }
        var outcome = refundPayment.handle(reference, amount);
        var status = outcome == RefundOutcome.REFUNDED ? HttpStatus.OK : HttpStatus.CONFLICT;
        return ResponseEntity.status(status).body(new RefundResponse(outcome.name()));
    }

    record RefundRequest(BigDecimal amount, String currency) {}

    record RefundResponse(String outcome) {}
}
