package com.example.payment.application.refund;

import com.example.payment.application.shared.ReceiptStore;
import com.example.payment.domain.refund.RefundOutcome;
import com.example.payment.domain.shared.Money;

/** Refunds one authorized payment and keeps a receipt of what the provider answered. */
public final class RefundPayment {

    private final RefundGateway gateway;
    private final ReceiptStore receipts;

    public RefundPayment(RefundGateway gateway, ReceiptStore receipts) {
        this.gateway = gateway;
        this.receipts = receipts;
    }

    public RefundOutcome handle(String reference, Money amount) {
        var outcome = gateway.refund(reference, amount);
        receipts.save(
                "refund-" + reference,
                amount.currency() + " " + amount.amount().toPlainString() + " -> " + outcome);
        return outcome;
    }
}
